import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import Optional


class MeridianClient:
    def __init__(self, base_url: str, api_key: str) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self._etag: Optional[str] = None

    # ── helpers ────────────────────────────────────────────────

    def _headers(self, extra: Optional[dict] = None) -> dict:
        h = {"Authorization": f"Bearer {self.api_key}", "Accept": "application/json"}
        if self._etag is not None:
            h["If-None-Match"] = self._etag
        if extra:
            h.update(extra)
        return h

    @staticmethod
    def _parse_retry_after(headers: dict) -> float:
        """Return a timestamp (time.time() + seconds) from Retry-After."""
        raw = headers.get("Retry-After", "")
        if not raw:
            return time.time() + 1
        try:
            # numeric form: seconds to wait
            return time.time() + float(raw)
        except ValueError:
            pass
        # HTTP-date form
        dt = parsedate_to_datetime(raw)
        return dt.timestamp()

    def _request(self, method: str, path: str, body=None) -> dict:
        """Send a request with rate-limit backoff and 304 caching."""
        import urllib.request
        import urllib.error

        url = f"{self.base_url}{path}"
        while True:
            data = json.dumps(body).encode() if body else None
            req = urllib.request.Request(
                url, data=data, method=method,
                headers=self._headers()
            )
            try:
                with urllib.request.urlopen(req) as resp:
                    etag = resp.headers.get("ETag")
                    if etag:
                        self._etag = etag
                    return json.loads(resp.read())
            except urllib.error.HTTPError as exc:
                code = exc.code
                if code == 304:
                    # nothing changed – return empty data with cached total
                    raise  # caller will handle
                if code == 429:
                    wait_until = self._parse_retry_after(dict(exc.headers))
                    sleep_secs = max(0, wait_until - time.time()) + 0.1
                    time.sleep(sleep_secs)
                    continue
                if code == 410:
                    # cursor expired – reset etag and re-raise for caller
                    self._etag = None
                raise

    def _fetch_page(self, cursor: Optional[str] = None, limit: int = 100) -> tuple[list[dict], Optional[str]]:
        """Fetch one page. Returns (payments, next_cursor)."""
        qs = f"?limit={limit}"
        if cursor is not None:
            qs += f"&cursor={cursor}"
        try:
            result = self._request("GET", f"/v1/payments{qs}")
        except urllib.error.HTTPError as exc:
            if exc.code == 304:
                # cached – nothing new
                return [], None
            raise
        return result["data"], result.get("next_cursor")

    # ── public API ─────────────────────────────────────────────

    def fetch_all_payments(self) -> list[dict]:
        """Fetch every payment, sorted oldest-first by instant."""
        payments: list[dict] = []
        cursor = None
        while True:
            try:
                page, next_cursor = self._fetch_page(cursor=cursor)
            except urllib.error.HTTPError as exc:
                if exc.code == 410:
                    # cursor expired – restart from the beginning
                    # keep what we already have, restart pagination
                    payments.clear()
                    cursor = None
                    continue
                raise
            payments.extend(page)
            if next_cursor is None:
                break
            cursor = next_cursor
        # sort by instant (UTC), not by string
        payments.sort(key=lambda p: _to_utc(p["created_at"]))
        return payments

    def total_count(self) -> int:
        """Return the total number of payments in the collection."""
        result = self._request("GET", "/v1/payments?limit=1")
        return result["total"]

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        """Create a payment. Safe to call repeatedly with the same key."""
        import urllib.error
        body = {"amount_minor": amount_minor, "currency": currency}
        extra_headers = {"Idempotency-Key": idempotency_key, "Content-Type": "application/json"}
        try:
            result = self._request("POST", "/v1/payments", body=body)
            return result["id"]
        except urllib.error.HTTPError as exc:
            if exc.code == 409:
                # duplicate – the payment was already created
                data = json.loads(exc.read())
                return data["payment_id"]
            raise


def _to_utc(iso_str: str) -> datetime:
    """Parse an RFC-3339 timestamp and return a timezone-aware UTC datetime."""
    dt = datetime.fromisoformat(iso_str)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)
