from typing import Optional


class Store:
    def __init__(self, path: str) -> None:
        self._path = path
        conn = sqlite3.connect(path)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS payments (
                id TEXT PRIMARY KEY,
                amount_minor INTEGER NOT NULL,
                currency TEXT NOT NULL,
                created_at TEXT NOT NULL,
                status TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
            """
        )
        conn.commit()
        self._conn = conn

    def _tx(self) -> sqlite3.Connection:
        return self._conn

    def upsert_many(self, payments: list[dict]) -> int:
        """Insert or update payments. Returns count of newly inserted rows."""
        conn = self._tx()
        before = conn.execute("SELECT COUNT(*) FROM payments").fetchone()[0]
        for p in payments:
            conn.execute(
                "INSERT OR REPLACE INTO payments (id, amount_minor, currency, created_at, status) "
                "VALUES (?, ?, ?, ?, ?)",
                (p["id"], p["amount_minor"], p["currency"], p["created_at"], p["status"]),
            )
        conn.commit()
        after = conn.execute("SELECT COUNT(*) FROM payments").fetchone()[0]
        return after - before

    def all_payments(self) -> list[dict]:
        """Return all payments, oldest first by instant."""
        rows = self._tx().execute(
            "SELECT id, amount_minor, currency, created_at, status FROM payments ORDER BY rowid"
        ).fetchall()
        return [
            {
                "id": r[0],
                "amount_minor": r[1],
                "currency": r[2],
                "created_at": r[3],
                "status": r[4],
            }
            for r in rows
        ]

    def count(self) -> int:
        return self._tx().execute("SELECT COUNT(*) FROM payments").fetchone()[0]

    def last_sync(self) -> Optional[str]:
        row = self._tx().execute(
            "SELECT value FROM meta WHERE key='last_sync'"
        ).fetchone()
        return row[0] if row else None

    def set_last_sync(self, when: str) -> None:
        self._tx().execute(
            "INSERT OR REPLACE INTO meta (key, value) VALUES ('last_sync', ?)",
            (when,),
        )
        self._tx().commit()
