<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>VendorSync</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         background: #f5f7fa; color: #1a1a2e; padding: 2rem; max-width: 860px; margin: 0 auto; }
  h1 { font-size: 1.5rem; margin-bottom: 1rem; }

  .summary { background: #fff; border-radius: 8px; padding: 1rem 1.25rem;
             box-shadow: 0 1px 3px rgba(0,0,0,.08); margin-bottom: 1rem; display: flex;
             align-items: center; justify-content: space-between; flex-wrap: wrap; gap: .75rem; }
  .summary .count { font-size: 1.125rem; font-weight: 600; }
  .summary .total { font-size: 1.125rem; color: #2d6a4f; font-weight: 600; }
  .summary .synced { font-size: .85rem; color: #666; }

  button { background: #2563eb; color: #fff; border: none; padding: .5rem 1.1rem;
           border-radius: 6px; font-size: .9rem; cursor: pointer; }
  button:hover { background: #1d4ed8; }
  button:disabled { opacity: .5; cursor: not-allowed; }

  table { width: 100%; border-collapse: collapse; background: #fff;
          border-radius: 8px; overflow: hidden;
          box-shadow: 0 1px 3px rgba(0,0,0,.08); }
  th { text-align: left; padding: .65rem 1rem; background: #f0f2f5;
       font-size: .75rem; text-transform: uppercase; letter-spacing: .04em; color: #555; }
  td { padding: .55rem 1rem; border-top: 1px solid #eee; font-size: .9rem; }
  td.amount { text-align: right; font-variant-numeric: tabular-nums; }
  td.status { white-space: nowrap; }

  .badge { display: inline-block; padding: .15em .5em; border-radius: 4px;
           font-size: .78rem; font-weight: 500; }
  .badge-settled { background: #d1fae5; color: #065f46; }
  .badge-pending  { background: #fef3c7; color: #92400e; }
  .badge-other    { background: #e5e7eb; color: #374151; }

  .state { text-align: center; padding: 3rem 1rem; color: #666; }
  .state.loading { font-size: 1rem; }
  .state.empty   { font-size: 1rem; }
  .state.error   { color: #b91c1c; font-size: 1rem; }
  .state.error span { display: block; margin-top: .5rem; font-size: .85rem; color: #666; }
</style>
</head>
<body>

<h1>VendorSync</h1>

<div class="summary" id="summary">
  <span class="count" id="payCount">&mdash;</span>
  <span class="total" id="payTotal">&mdash;</span>
  <span class="synced" id="lastSync">&mdash;</span>
  <button id="syncBtn">Sync now</button>
</div>

<div id="state"></div>
<table id="tbl" style="display:none">
  <thead><tr><th>Date</th><th class="amount">Amount</th><th>Status</th></tr></thead>
  <tbody id="tbody"></tbody>
</table>

<script>
const API = '';

function fmtEUR(minor) {
  return '\u20ac' + (minor / 100).toLocaleString('de-DE', {minimumFractionDigits: 2, maximumFractionDigits: 2});
}

function fmtDate(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'numeric'});
}

function badge(status) {
  var cls = status === 'settled' ? 'badge-settled' : status === 'pending' ? 'badge-pending' : 'badge-other';
  return '<span class="badge ' + cls + '">' + status + '</span>';\n}

async function json(url) {
  var r = await fetch(API + url);
  if (!r.ok) throw new Error(r.status + ' ' + (await r.text()).slice(0,120));
  return r.json();
}

function renderSummary(h) {
  document.getElementById('payCount').textContent = h.payments + ' payment' + (h.payments !== 1 ? 's' : '');
  var syncEl = document.getElementById('lastSync');
  syncEl.textContent = h.last_sync ? 'Last synced: ' + new Date(h.last_sync).toLocaleString() : 'Never synced';
}

async function refresh() {
  try {
    var h = await json('/api/health');
    renderSummary(h);
    if (h.payments === 0) {
      document.getElementById('state').innerHTML = '<div class="state empty">No payments yet. Click <strong>Sync now</strong> to pull from Meridian.</div>';
      document.getElementById('tbl').style.display = 'none';
      return;
    }
    var s = await json('/api/summary');
    document.getElementById('payTotal').textContent = fmtEUR(s.total_minor);
    // load payments
    var p = await json('/api/payments?limit=100');
    var html = '';
    p.data.forEach(function(row) {
      html += '<tr>'
            + '<td>' + fmtDate(row.created_at) + '</td>'
            + '<td class="amount">' + fmtEUR(row.amount_minor) + '</td>'
            + '<td class="status">' + badge(row.status) + '</td></tr>';
    });
    document.getElementById('tbody').innerHTML = html;
    document.getElementById('state').innerHTML = '';
    document.getElementById('tbl').style.display = '';
  } catch(e) {
    document.getElementById('state').innerHTML = '<div class="state error">Could not reach the backend.<span>' + e.message + '</span></div>';
    document.getElementById('tbl').style.display = 'none';
  }
}

async function doSync() {
  var btn = document.getElementById('syncBtn');
  btn.disabled = true; btn.textContent = 'Syncing…';
  try {
    await json('/api/sync');
    await refresh();
  } catch(e) {
    alert('Sync failed: ' + e.message);
  } finally {
    btn.disabled = false; btn.textContent = 'Sync now';
  }
}

document.getElementById('syncBtn').addEventListener('click', doSync);
refresh();
</script>
</body>
</html>
